theorem IsFinitelySemisimple.triangularizable_iff_diagonalizable {R M : Type*} 
    [CommRing R] [AddCommGroup M] [Module R M] {f : Module.End R M} 
    (hf : f.IsFinitelySemisimple) :
    (⨆ μ : R, f.maxGenEigenspace μ) = ⊤ ↔ (⨆ μ : R, f.eigenspace μ) = ⊤ := by
  simp only [hf.maxGenEigenspace_eq_eigenspace]
